// Original TTIsland Native Wi-Fi controller. Passwords are never returned or logged.
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.ComponentModel;
using System.Security;
using System.Threading;
namespace TTIsland.Native {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct WifiInterface { public Guid Id; [MarshalAs(UnmanagedType.ByValTStr,SizeConst=256)]public string Name;public uint State; }
 [StructLayout(LayoutKind.Sequential)] struct Ssid {public uint Length;[MarshalAs(UnmanagedType.ByValArray,SizeConst=32)] public byte[] Bytes;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct AvailableNetwork {
  [MarshalAs(UnmanagedType.ByValTStr,SizeConst=256)]public string Profile;public Ssid Ssid;public uint BssType;public uint Bssids;public int Connectable;public uint Reason;public uint PhyCount;[MarshalAs(UnmanagedType.ByValArray,SizeConst=8)]public uint[] Phys;public int MorePhys;public uint Signal;public int Secure;public uint Auth;public uint Cipher;public uint Flags;public uint Reserved;
 }
 [StructLayout(LayoutKind.Sequential)] struct RadioState {public uint Index;public uint Software;public uint Hardware;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct ConnectionParams {public uint Mode;[MarshalAs(UnmanagedType.LPWStr)] public string Profile;public IntPtr Ssid;public IntPtr BssidList;public uint BssType;public uint Flags;}
 public class WifiAdapter {public string id;public string name;public bool enabled;public bool hardwareOff;public uint state;public string error;}
 public class WifiNetwork {public string ssid;public string ssidHex;public string profile;public string adapterId;public uint signal;public bool secured;public uint auth;public uint cipher;public bool connected;public bool connectable;public string security;}
 public class WifiSnapshot {public WifiAdapter[] adapters;public WifiNetwork[] networks;public string[] warnings;}
 public static class Wifi {
  [DllImport("wlanapi.dll")]static extern uint WlanOpenHandle(uint version,IntPtr reserved,out uint negotiated,out IntPtr handle);
  [DllImport("wlanapi.dll")]static extern uint WlanCloseHandle(IntPtr handle,IntPtr reserved);
  [DllImport("wlanapi.dll")]static extern void WlanFreeMemory(IntPtr ptr);
  [DllImport("wlanapi.dll")]static extern uint WlanEnumInterfaces(IntPtr handle,IntPtr reserved,out IntPtr list);
  [DllImport("wlanapi.dll")]static extern uint WlanQueryInterface(IntPtr handle,ref Guid id,uint opcode,IntPtr reserved,out uint size,out IntPtr data,out uint type);
  [DllImport("wlanapi.dll")]static extern uint WlanSetInterface(IntPtr handle,ref Guid id,uint opcode,uint size,ref RadioState data,IntPtr reserved);
  [DllImport("wlanapi.dll")]static extern uint WlanGetAvailableNetworkList(IntPtr handle,ref Guid id,uint flags,IntPtr reserved,out IntPtr list);
  [DllImport("wlanapi.dll")]static extern uint WlanScan(IntPtr handle,ref Guid id,IntPtr ssid,IntPtr ie,IntPtr reserved);
  [DllImport("wlanapi.dll",CharSet=CharSet.Unicode)]static extern uint WlanSetProfile(IntPtr handle,ref Guid id,uint flags,string xml,string security,int overwrite,IntPtr reserved,out uint reason);
  [DllImport("wlanapi.dll",CharSet=CharSet.Unicode)]static extern uint WlanDeleteProfile(IntPtr handle,ref Guid id,string name,IntPtr reserved);
  [DllImport("wlanapi.dll")]static extern uint WlanConnect(IntPtr handle,ref Guid id,ref ConnectionParams data,IntPtr reserved);
  [DllImport("wlanapi.dll")]static extern uint WlanDisconnect(IntPtr handle,ref Guid id,IntPtr reserved);
  [DllImport("wlanapi.dll",CharSet=CharSet.Unicode)]static extern uint WlanReasonCodeToString(uint code,uint size,StringBuilder text,IntPtr reserved);
  sealed class Handle:IDisposable {public IntPtr Value;public Handle(){uint n;Check(WlanOpenHandle(2,IntPtr.Zero,out n,out Value));}public void Dispose(){if(Value!=IntPtr.Zero){WlanCloseHandle(Value,IntPtr.Zero);Value=IntPtr.Zero;}}}
  static void Check(uint code){if(code==0)return;if(code==5)throw new InvalidOperationException("Windows запретила доступ. Для списка Wi-Fi в новых Windows 11 разреши геолокацию для классических приложений; управление радио также может быть запрещено политикой или драйвером.");if(code==1062)throw new InvalidOperationException("Служба автонастройки WLAN остановлена.");throw new Win32Exception((int)code);}
  static string Reason(uint code){var b=new StringBuilder(1024);return WlanReasonCodeToString(code,1024,b,IntPtr.Zero)==0?b.ToString():"Код Wi-Fi: "+code;}
  static List<WifiInterface> Interfaces(IntPtr h){IntPtr data=IntPtr.Zero;try{Check(WlanEnumInterfaces(h,IntPtr.Zero,out data));int count=Marshal.ReadInt32(data);if(count<0||count>64)throw new InvalidOperationException("Некорректный список адаптеров");var list=new List<WifiInterface>();int size=Marshal.SizeOf(typeof(WifiInterface));for(int i=0;i<count;i++)list.Add((WifiInterface)Marshal.PtrToStructure(IntPtr.Add(data,8+i*size),typeof(WifiInterface)));return list;}finally{if(data!=IntPtr.Zero)WlanFreeMemory(data);}}
  static Guid Adapter(IntPtr h,string id){Guid guid;if(!Guid.TryParse(id,out guid))throw new ArgumentException("Некорректный адаптер");foreach(var item in Interfaces(h))if(item.Id==guid)return guid;throw new InvalidOperationException("Адаптер отключён или удалён");}
  static RadioState[] Radio(IntPtr h,Guid id){uint size,type;IntPtr data=IntPtr.Zero;try{Check(WlanQueryInterface(h,ref id,4,IntPtr.Zero,out size,out data,out type));int count=Marshal.ReadInt32(data);if(count<0||count>64||size<4+count*12)throw new InvalidOperationException("Неизвестное состояние радио");var list=new List<RadioState>();for(int i=0;i<count;i++)list.Add((RadioState)Marshal.PtrToStructure(IntPtr.Add(data,4+i*12),typeof(RadioState)));return list.ToArray();}finally{if(data!=IntPtr.Zero)WlanFreeMemory(data);}}
  static List<AvailableNetwork> Networks(IntPtr h,Guid id){IntPtr data=IntPtr.Zero;try{Check(WlanGetAvailableNetworkList(h,ref id,2,IntPtr.Zero,out data));int count=Marshal.ReadInt32(data);if(count<0||count>8192)throw new InvalidOperationException("Слишком много сетей");var list=new List<AvailableNetwork>();int size=Marshal.SizeOf(typeof(AvailableNetwork));for(int i=0;i<count;i++)list.Add((AvailableNetwork)Marshal.PtrToStructure(IntPtr.Add(data,8+i*size),typeof(AvailableNetwork)));return list;}finally{if(data!=IntPtr.Zero)WlanFreeMemory(data);}}
  static string Hex(Ssid ssid){int n=(int)Math.Min(ssid.Length,32);return BitConverter.ToString(ssid.Bytes,0,n).Replace("-","");}
  public static WifiSnapshot Snapshot(bool scan){using(var h=new Handle()){var adapters=new List<WifiAdapter>();var networks=new List<WifiNetwork>();var warnings=new List<string>();foreach(var item in Interfaces(h.Value)){Guid id=item.Id;var a=new WifiAdapter{id=id.ToString(),name=item.Name,state=item.State};bool radioKnown=false;try{var phys=Radio(h.Value,id);radioKnown=true;foreach(var phy in phys){if(phy.Software==1&&phy.Hardware==1)a.enabled=true;if(phy.Hardware==2)a.hardwareOff=true;}}catch(Exception e){a.error=e.Message;warnings.Add(e.Message);}adapters.Add(a);if(radioKnown&&!a.enabled)continue;if(scan){uint error=WlanScan(h.Value,ref id,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero);if(error!=0)warnings.Add("Сканирование: "+new Win32Exception((int)error).Message);else Thread.Sleep(1800);}try{foreach(var n in Networks(h.Value,id)){if(n.Ssid.Length==0)continue;networks.Add(new WifiNetwork{ssid=Encoding.UTF8.GetString(n.Ssid.Bytes,0,(int)Math.Min(32,n.Ssid.Length)),ssidHex=Hex(n.Ssid),profile=n.Profile,adapterId=id.ToString(),signal=n.Signal,secured=n.Secure!=0,auth=n.Auth,cipher=n.Cipher,connected=(n.Flags&1)!=0,connectable=n.Connectable!=0,security=n.Auth==9?"WPA3":n.Auth==7?"WPA3 Enterprise":n.Auth==6?"WPA2":n.Auth==4?"WPA":n.Secure==0?"Открытая":"Защищённая"});}}catch(Exception e){warnings.Add(e.Message);}}return new WifiSnapshot{adapters=adapters.ToArray(),networks=networks.ToArray(),warnings=warnings.ToArray()};}}
  public static WifiSnapshot Power(string adapterId,bool enabled){using(var h=new Handle()){Guid id=Adapter(h.Value,adapterId);var phys=Radio(h.Value,id);if(phys.Length==0)throw new InvalidOperationException("Драйвер не сообщил радио");foreach(var phy in phys){if(enabled&&phy.Hardware==2)throw new InvalidOperationException("Wi-Fi отключён аппаратно. Проверь кнопку или переключатель ноутбука.");var next=new RadioState{Index=phy.Index,Software=enabled?1u:2u,Hardware=0};Check(WlanSetInterface(h.Value,ref id,4,12,ref next,IntPtr.Zero));}Thread.Sleep(500);}var result=Snapshot(false);foreach(var a in result.adapters)if(a.id==adapterId&&a.enabled!=enabled)throw new InvalidOperationException("Windows пока не подтвердила переключение. Обнови список.");return result;}
  static string Escape(string value){return SecurityElement.Escape(value)??"";}
  public static void Connect(string adapterId,string ssidHex,string profile,string password,bool remember){using(var h=new Handle()){Guid id=Adapter(h.Value,adapterId);AvailableNetwork? selected=null;foreach(var network in Networks(h.Value,id))if(string.Equals(Hex(network.Ssid),ssidHex,StringComparison.OrdinalIgnoreCase)&&(string.IsNullOrEmpty(profile)||network.Profile==profile)){selected=network;break;}if(!selected.HasValue)throw new InvalidOperationException("Сеть больше не видна. Обнови список.");var n=selected.Value;string name=n.Profile;bool temporary=false;uint mode=0;
   if(string.IsNullOrEmpty(name)||!string.IsNullOrEmpty(password)){if(n.Secure!=0&&n.Auth!=6&&n.Auth!=9)throw new InvalidOperationException("Для этой сети нужен предварительно настроенный профиль Windows (Enterprise/WEP/WPA). Обычный пароль поддерживается для WPA2-Personal и WPA3-Personal.");if(n.Secure!=0&&(password==null||password.Length<8||password.Length>63))throw new ArgumentException("Пароль должен содержать 8–63 символа");if(n.Secure!=0)foreach(char ch in password)if(ch<32||ch>126)throw new ArgumentException("Этот режим принимает пароль из печатных ASCII-символов");name=string.IsNullOrEmpty(n.Profile)?"TTIsland-"+ssidHex:n.Profile;string auth=n.Secure==0?"open":n.Auth==9?"WPA3SAE":"WPA2PSK";string shared=n.Secure==0?"":"<sharedKey><keyType>passPhrase</keyType><protected>false</protected><keyMaterial>"+Escape(password)+"</keyMaterial></sharedKey>";string xml="<?xml version=\"1.0\"?><WLANProfile xmlns=\"http://www.microsoft.com/networking/WLAN/profile/v1\"><name>"+Escape(name)+"</name><SSIDConfig><SSID><hex>"+ssidHex+"</hex></SSID></SSIDConfig><connectionType>ESS</connectionType><connectionMode>manual</connectionMode><MSM><security><authEncryption><authentication>"+auth+"</authentication><encryption>"+(n.Secure==0?"none":"AES")+"</encryption><useOneX>false</useOneX></authEncryption>"+shared+"</security></MSM></WLANProfile>";
    if(remember){uint reason;uint code=WlanSetProfile(h.Value,ref id,2,xml,null,1,IntPtr.Zero,out reason);if(code!=0)throw new InvalidOperationException("Профиль не принят: "+Reason(reason)+" ("+code+")");}else{mode=1;name=xml;temporary=true;}
   }
   var request=new ConnectionParams{Mode=mode,Profile=name,Ssid=IntPtr.Zero,BssidList=IntPtr.Zero,BssType=1,Flags=0};Check(WlanConnect(h.Value,ref id,ref request,IntPtr.Zero));bool connected=false;for(int attempt=0;attempt<24;attempt++){Thread.Sleep(500);foreach(var current in Networks(h.Value,id))if((current.Flags&1)!=0&&Hex(current.Ssid)==ssidHex){connected=true;break;}if(connected)break;}
   if(!connected)throw new InvalidOperationException("Подключение не подтверждено. Проверь пароль, сигнал и доступность сети; затем обнови список.");if(temporary)name=null;
  }}
  public static void Disconnect(string adapterId){using(var h=new Handle()){Guid id=Adapter(h.Value,adapterId);Check(WlanDisconnect(h.Value,ref id,IntPtr.Zero));}}
  public static void Forget(string adapterId,string profile){if(string.IsNullOrEmpty(profile)||profile.Length>255)throw new ArgumentException("Некорректный профиль");using(var h=new Handle()){Guid id=Adapter(h.Value,adapterId);bool found=false;foreach(var n in Networks(h.Value,id))if(n.Profile==profile){found=true;break;}if(!found)throw new InvalidOperationException("Профиль больше не доступен в списке сетей");Check(WlanDeleteProfile(h.Value,ref id,profile,IntPtr.Zero));}}
 }
}
